    // 1. Remove spaces to ignore them as per requirements
    clean: $x ~ " ";

    // 2. Identify open '(' (1) and close ')' (-1)
    //    We use the 'asc' technique to map characters to integers or simple comparison
    //    '(' is 40, ')' is 41 in ASCII.
    //    However, a more readable approach:
    //    If char is '(', val is 1. If ')', val is -1. Else 0.
